// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(depositor != address(0));

        ExpensiveFallback malicious = new ExpensiveFallback();

        vm.deal(depositor, amount);

        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amount}("");

        c = new keepMyEther();
        vm.deal(depositor, amount);
        vm.prank(address(malicious));
        vm.deal(address(malicious), amount);
        (bool okDeposit,) = address(c).call{value: amount}("");

        bool okWithdraw;
        vm.prank(address(malicious));
        try c.withdraw() {
            okWithdraw = true;
        } catch {
            okWithdraw = false;
        }

        assertTrue(address(c).balance == 0);
    }
}

contract ExpensiveFallback {
    fallback() external payable {
        uint256 x = 0;
        for (uint256 i = 0; i < 1000; i++) {
            x += i;
        }
        expensive = x;
    }
    uint256 public expensive;
}
